"""L0 – the virtual-structure reference (racetrack) generated by the leader/GCS.

The reference is the virtual rigid body of Part 13 (13_virtual_structures.html) with
state xi = (p_c, psi_c, V_c, omega_c, h_c).  On straight legs omega_c = 0; in the 180°
coordinated turns omega_c = g*tan(phi_c)/V_c (Part 16 §2).  The same propagation model is
used by every UAV's estimator (Part 8 §5, dynamic leader) – see estimator.py.
"""
from dataclasses import dataclass
import numpy as np
from .vehicle import G, wrap, turn_radius

# indices into xi
PN, PE, PSI, V, OMEGA, H = range(6)


def propagate(xi, dt):
    """Euler propagation of a reference state (Part 13 §2):
    p_c += V_c*[cos psi_c, sin psi_c]*dt,  psi_c += omega_c*dt.  Pure function."""
    out = np.array(xi, dtype=float)
    out[PN] += xi[V] * np.cos(xi[PSI]) * dt
    out[PE] += xi[V] * np.sin(xi[PSI]) * dt
    out[PSI] = wrap(xi[PSI] + xi[OMEGA] * dt)
    return out


@dataclass
class Racetrack:
    """Straight legs of length `leg` joined by 180° turns at bank phi_c (Part 17 §5, racetrack
    = Dubins-like path).  Mode switching by distance travelled on the leg / angle turned.
    turn_dir = +1 turns right (clockwise, positive omega in NED), -1 turns left.
    phi_dot_max limits the roll rate of the virtual lead (Part 16 §5): the bank ramps 0 -> phi_c
    on entry and back on exit, so omega_c is continuous and the slot speeds change at a rate the
    wingmen can follow with a_max.  phi_dot_max = inf gives the pure step of SIM_SPEC."""
    V_c: float
    phi_c: float
    leg: float
    h_c: float
    p0: tuple = (0.0, 0.0)
    psi0: float = 0.0
    turn_dir: int = 1
    phi_dot_max: float = np.inf

    def __post_init__(self):
        self.xi = np.array([self.p0[0], self.p0[1], self.psi0, self.V_c, 0.0, self.h_c])
        self.mode, self.progress, self.phi, self.theta_in = "leg", 0.0, 0.0, None

    @property
    def omega_turn(self):
        return G * np.tan(self.phi_c) / self.V_c

    @property
    def radius(self):
        return turn_radius(self.V_c, self.phi_c)

    def step(self, dt):
        """Advance the reference by dt and return the new xi (a copy)."""
        if self.mode == "turn":
            # hold full bank until the roll-out (which mirrors the roll-in angle theta_in) completes 180°
            hold = self.theta_in is None or self.progress < np.pi - self.theta_in
            dphi = np.clip((self.phi_c if hold else 0.0) - self.phi, -self.phi_dot_max * dt, self.phi_dot_max * dt)
            self.phi += dphi
            if self.theta_in is None and self.phi >= self.phi_c - 1e-12:
                self.theta_in = self.progress
            self.xi[OMEGA] = self.turn_dir * G * np.tan(self.phi) / self.V_c
            if not hold and self.phi <= 1e-12:
                self.mode, self.progress, self.phi, self.xi[OMEGA] = "leg", 0.0, 0.0, 0.0
        self.xi = propagate(self.xi, dt)
        if self.mode == "leg":
            self.progress += self.V_c * dt
            if self.progress >= self.leg:
                self.mode, self.progress, self.theta_in = "turn", 0.0, None
        else:
            self.progress += abs(self.xi[OMEGA]) * dt
        return self.xi.copy()

    def copy(self):
        r = Racetrack(self.V_c, self.phi_c, self.leg, self.h_c, self.p0, self.psi0, self.turn_dir, self.phi_dot_max)
        r.xi, r.mode, r.progress, r.phi, r.theta_in = self.xi.copy(), self.mode, self.progress, self.phi, self.theta_in
        return r
